import{_ as l,l as s,o as e,c as n,v as o,p as i,x as t,d as c,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"steal / no-force","description":"","frontmatter":{"title":"steal / no-force","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/steal-noforce.md","filePath":"cs/steal-noforce.md","lastUpdated":1789023840000}'),A={name:"cs/steal-noforce.md"};function f(p,a,h,_,u,B){const r=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="steal-no-force" tabindex="-1">steal / no-force <a class="header-anchor" href="#steal-no-force" aria-label="Permalink to &quot;steal / no-force&quot;">​</a></h1><div class="epigraph"><p>未提交事务的脏页可以被换出（steal）；提交时不必把所有脏页立刻刷数据文件（no-force）——前提是日志已经先落盘。</p><footer>—— 据 Gray and Reuter；Mohan 等 ARIES 对缓冲策略与 WAL 的整理</footer></div><p><a href="/cs/wal">上一课</a>钉死写顺序：日志先于数据页。本课不重讲 redo 记录长什么样。缺口是缓冲池政策：若禁止 steal，内存必须装下未提交脏页；若 force 到提交，提交延迟等于随机刷盘。steal + no-force 是高性能默认，把正确性全部压在日志与 pageLSN 上。ARIES 下一课展开重启。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>WAL 课留下「崩溃时靠日志」。缓冲仍要决定：脏页能否在提交前换出？提交时要不要把堆页刷完？四种组合里，steal/no-force 需要 UNDO（页上可能有未提交）与 REDO（提交的页可能还没刷）。缺口是<strong>把缓冲政策命名成恢复需求</strong>。</p><p><span class="marginnote">no-steal/force 几乎不用日志就能简单恢复，但吞吐不可接受。实践选 steal/no-force，用 ARIES 付复杂度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>换页时若页脏：先保证描述该页的日志已刷（WAL 规则），再把页写出——即使事务未提交（steal）。提交：刷到日志的提交记录，不必 force 数据页（no-force）。pageLSN 记录页上最后一次更新的日志地址，重启时判断要不要 REDO。</p>',8)),(e(),i(d,null,{default:t(()=>[E(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIRTY%5B%22%E6%9C%AA%E6%8F%90%E4%BA%A4%E8%84%8F%E9%A1%B5%22%5D%20--%3E%20STEAL%5B%22%E5%8F%AF%E4%BB%A5%E6%8D%A2%E5%87%BA%22%5D%0A%20%20COMMIT%5B%22%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20NF%5B%22%E5%8F%AA%E5%BC%BA%E5%88%B7%E6%97%A5%E5%BF%97%E4%B8%8D%E5%BC%BA%E5%88%B6%E6%95%B0%E6%8D%AE%E9%A1%B5%22%5D%0A%20%20STEAL%20--%3E%20UNDO%5B%22%E9%87%8D%E5%90%AF%E9%9C%80%E8%A6%81%20UNDO%22%5D%0A%20%20NF%20--%3E%20REDO%5B%22%E9%87%8D%E5%90%AF%E9%9C%80%E8%A6%81%20REDO%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>政策把 <a href="/cs/buffer-dirty">缓冲与脏页</a> 的 OS 直觉接到事务：OS 不知道提交点。日志是唯一把「已提交」钉在磁盘上的对象。后课 ARIES 的分析阶段要找出脏页表与活跃事务，正是因为 steal/no-force 制造了这两种不确定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把双写缓冲等厂商防撕裂页方案当 WAL 替代。重启三阶段下一课。</p><p>后课默认：缓冲可以偷页、提交可以不刷堆。崩溃恢复必须 REDO+UNDO。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>steal 允许未提交页下盘；no-force 允许提交后页仍只在缓存。</li><li>正确性靠 WAL 与 pageLSN。</li><li>ARIES 三阶段下一课。</li><li>出处：Gray and Reuter；Mohan et al. ARIES。</li></ul>',7))])}const S=l(A,[["render",f]]);export{m as __pageData,S as default};
